test('invoiceTotals includes discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 95000); // 10 * 9500
  assert.equal(totals.discount, 9500); // 95000 * 0.1
  assert.equal(totals.total, 85500); // 95000 - 9500
});

test('invoiceTotals with multiple lines with different discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // subtotal 95000, discount 9500
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 }, // subtotal 120000, discount 24000
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 33500); // 9500 + 24000
  assert.equal(totals.total, 181500); // 215000 - 33500
});

test('invoiceTotals with no discount has discount of 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 95000);
});

test('addLine accepts discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine validates discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  assert.deepEqual(addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: -5 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
  assert.deepEqual(addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 105 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
});

test('addLine to existing SKU updates discountPercent if provided', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].qty, 10);
  assert.equal(r2.value.lines[0].discountPercent, 20);
});

