    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: -1 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 'not a number' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice accepts decimal discount percentages', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
