  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('lineDiscount calculates discount correctly', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 10 }), 9500); // 950 * 0.1 = 95 euros = 9500 cents
  assert.equal(lineDiscount({ qty: 1, unitPrice: 120000, discountPercent: 10 }), 12000); // 1200 * 0.1 = 120 euros = 12000 cents
});

test('lineDiscount defaults to 0% if discountPercent not provided', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500 }), 0);
});

test('lineDiscount is clamped to 0', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 0 }), 0);
});

test('invoiceTotals includes discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 95000); // 10 * 9500
  assert.equal(totals.discount, 9500); // 95000 * 0.1
  assert.equal(totals.total, 85500); // 95000 - 9500
});

test('invoiceTotals with multiple lines with different discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // subtotal 95000, discount 9500
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 }, // subtotal 120000, discount 24000
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 33500); // 9500 + 24000
  assert.equal(totals.total, 181500); // 215000 - 33500
});

test('invoiceTotals with no discount has discount of 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
