import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount } from '../src/invoices.js';

test('createInvoice creates a draft invoice with product details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2024-01-15');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);

  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);

  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].name, 'Logo package');
  assert.equal(r.value.lines[1].qty, 1);
  assert.equal(r.value.lines[1].unitPrice, 120000);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for missing date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice returns DATE_INVALID for malformed date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '01-15-2024',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice returns DATE_INVALID for non-existent date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });

  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });

  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });

  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns QTY_INVALID for fractional quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });

  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns UNKNOWN_SKU for non-existent SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice stops at first error', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'UNKNOWN-SKU', qty: 1 },
    ],
  });

  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice works with various VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 9);
  assert.equal(r.value.lines[1].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const inputLines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const originalLines = JSON.parse(JSON.stringify(inputLines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: inputLines,
  });

  assert.deepEqual(inputLines, originalLines);
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal works with zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('invoiceTotals calculates correct subtotal and total', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 95000 + 120000);
  assert.equal(totals.total, 215000);
});

test('invoiceTotals works with empty lines array', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals works with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 6000 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.total, 30000);
});

test('invoiceTotals with created invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 10 * 9500 + 1 * 120000);
  assert.equal(totals.total, 95000 + 120000);
});

test('addLine adds a new line to draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[1].name, 'Logo package');
  assert.equal(r2.value.lines[1].qty, 1);
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[0].qty, 8);
});

test('addLine returns QTY_INVALID for non-positive quantity', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  assert.deepEqual(addLine(r1.value, { sku: 'LOGO-PACK', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(r1.value, { sku: 'LOGO-PACK', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(r1.value, { sku: 'LOGO-PACK', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine returns UNKNOWN_SKU for non-existent SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  assert.deepEqual(addLine(r1.value, { sku: 'UNKNOWN-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const originalLines = JSON.parse(JSON.stringify(r1.value.lines));

  addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });

  assert.deepEqual(r1.value.lines, originalLines);
});

test('removeLine removes a line from draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(r1.ok, true);
  const r2 = removeLine(r1.value, 'DEV-HOUR');

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
