test('issueInvoice assigns a number and changes status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const r2 = issueInvoice(r1.value, []);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2024-0001');
  assert.equal(r2.value.status, 'issued');
});

test('issueInvoice increments counter for same year', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
  const r2 = issueInvoice(r1.value, existingNumbers);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2024-0003');
});

test('issueInvoice resets counter for different year', () => {
