    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002', 'INV-2024-0100'];
  const r2 = issueInvoice(r1.value, existingNumbers);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2025-0001');
});

test('issueInvoice returns NOT_DRAFT for non-draft invoice', () => {
